import{_ as o,o as d,c,a5 as p}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"SpringMVC 的基本概念","description":"","frontmatter":{"title":"SpringMVC 的基本概念","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的基本概念.md","filePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的基本概念.md"}'),r={name:"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的基本概念.md"};function t(n,e,s,i,a,g){return d(),c("div",null,[...e[0]||(e[0]=[p("<div><p><strong>关于三层架构和</strong> <code>MVC</code></p><p><strong>三层架构</strong> 我们的开发架构一般都是基于两种形式，一种是 <code>C/S</code> 架构，也就是客户端<code>/</code>服务器，另一种是 <code>B/S</code> 架构，也就是浏览器服务器。</p><p>在 <code>JavaEE</code> 开发中，几乎全都是基于 <code>B/S</code> 架构的开发。那么在 <code>B/S</code> 架构中，系统标准的三层架构包括：表现层、业务层、持久层。三层架构在我们的实际开发中使用的非常多，所以我们课程中的案例也都是基于三层架构设计的。</p><p>三层架构中，每一层各司其职： <strong>表现层：</strong> 也就是我们常说的<code>web</code>层。它负责接收客户端请求，向客户端响应结果，通常客户端使用<code>http</code>协议请求<code>web</code> 层，<code>web</code> 需要接收 <code>http</code> 请求，完成 <code>http</code> 响应。 表现层包括展示层和控制层：控制层负责接收请求，展示层负责结果的展示。 表现层依赖业务层，接收到客户端请求一般会调用业务层进行业务处理，并将处理结果响应给客户端。 表现层的设计一般都使用</p><p><code>MVC</code></p><p>模型。（<code>MVC</code> 是表现层的设计模型，和其他层没有关系）</p><p><strong>业务层：</strong> 也就是我们常说的 <code>service</code> 层。它负责业务逻辑处理，和我们开发项目的需求息息相关。<code>web</code> 层依赖业务层，但是业务层不依赖 <code>web</code> 层。 业务层在业务处理时可能会依赖持久层，如果要对数据持久化需要保证事务一致性。（也就是我们说的，事务应该放到业务层来控制）</p><p><strong>持久层：</strong> 也就是我们是常说的 <code>dao</code> 层。负责数据持久化，包括数据层即数据库和数据访问层，数据库是对数据进行持久化的载体，数据访问层是业务层和持久层交互的接口，业务层需要通过数据访问层将数据持久化到数据库中。通俗的讲，持久层就是和数据库交互，对数据库表进行曾删改查的。</p><p><code>MVC</code> <strong>模型</strong><code>MVC</code> 全名是 <code>Model View Controller</code>，是模型<code>(model)</code>－视图<code>(view)</code>－控制器<code>(controller)</code>的缩写，是一种用于设计创建 <code>Web</code> 应用程序表现层的模式。<code>MVC</code> 中每个部分各司其职：</p><p><code>Model</code><strong>（模型）：</strong> 通常指的就是我们的数据模型。作用一般情况下用于封装数据。</p><p><code>View</code></p><p><strong>（视图）：</strong> 通常指的就是我们的</p><p><code>jsp</code></p><p>或者 <code>html</code>。作用一般就是展示数据的。 通常视图是依据模型数据创建的。￼是应用程序中处理用户交互的部分。作用一般就是处理程序逻辑的。</p><p>它相对于前两个不是很好理解，这里举个例子： 例如： 我们要保存一个用户的信息，该用户信息中包含了姓名，性别，年龄等等。 这时候表单输入要求年龄必须是</p><p><code>1~100</code></p><p>之间的整数。姓名和性别不能为空。并且把数据填充 到模型之中。 此时除了</p><p><code>js</code></p><p>的校验之外，服务器端也应该有数据准确性的校验，那么校验就是控制器的该做 的。 当校验失败后，由控制器负责把错误页面展示给使用者。 如果校验成功，也是控制器负责把数据填充到模型，并且调用业务层实现完整的业务需求。</p><p><code>SpringMVC</code> <strong>概述</strong><code>SpringMVC</code> 是一种基于 <code>Java</code> 的实现 <code>MVC</code> 设计模型的请求驱动类型的轻量级 <code>Web</code> 框架，属于 <code>Spring</code> <code>FrameWork</code> 的后续产品，已经融合在 <code>Spring Web Flow</code> 里面。<code>Spring</code> 框架提供了构建 <code>Web</code> 应用程序的全功能 <code>MVC</code> 模块。使用 <code>Spring</code> 可插入的 <code>MVC</code> 架构，从而在使用 <code>Spring</code> 进行 <code>WEB</code> 开发时，可以选择使用 <code>Spring</code> 的 <code>Spring MVC</code> 框架或集成其他 <code>MVC</code> 开发框架，如 <code>Struts1(</code>现在一般不用<code>)</code>，<code>Struts2</code> 等。</p><p><code>SpringMVC</code> 已经成为目前最主流的 <code>MVC</code> 框架之一，并且随着 <code>Spring3.0</code> 的发布，全面超越 <code>Struts2</code>，成为最优秀的 <code>MVC</code> 框架。 它通过一套注解，让一个简单的 <code>Java</code> 类成为处理请求的控制器，而无须实现任何接口。同时它还支持<code>RESTful</code> 编程风格的请求。 <code>SpringMVC</code> <strong>在三层架构的位置</strong></p><p><code>SpringMVC</code> <strong>的优势</strong><code>1</code>、清晰的角色划分： 前端控制器（<code>DispatcherServlet</code>） 请求到处理器映射（<code>HandlerMapping</code>） 处理器适配器（<code>HandlerAdapter</code>） 视图解析器（<code>ViewResolver</code>） 处理器或页面控制器（<code>Controller</code>） 验证器（</p><p><code>Validator</code></p><p>） 命令对象（<code>Command</code> 请求参数绑定到的对象就叫命令对象） 表单对象（<code>Form Object</code> 提供给表单展示和提交到的对象就叫表单对象） <code>2</code>、分工明确，而且扩展点相当灵活，可以很容易扩展，虽然几乎不需要。</p><p><code>3</code></p><p>、由于命令对象就是一个 <code>POJO</code>，无需继承框架特定 <code>API</code>，可以使用命令对象直接作为业务对象。</p><p><code>4</code></p><p>、和 <code>Spring</code> 其他框架无缝集成，是其它 <code>Web</code> 框架所不具备的。</p><p><code>5</code></p><p>、可适配，通过 <code>HandlerAdapter</code> 可以支持任意的类作为处理器。</p><p><code>6</code></p><p>、可定制性，<code>HandlerMapping</code>、<code>ViewResolver</code> 等能够非常简单的定制。</p><p><code>7</code></p><p>、功能强大的数据验证、格式化、绑定机制。</p><p><code>8</code></p><p>、利用 <code>Spring</code> 提供的 <code>Mock</code> 对象能够非常简单的进行 <code>Web</code> 层单元测试。</p><p><code>9</code></p><p>、本地化、主题的解析的支持，使我们更容易进行国际化和主题的切换。</p><p><code>10</code></p><p>、强大的 <code>JSP</code> 标签库，使 <code>JSP</code> 编写更容易。 ………………还有比如<code>RESTful</code>风格的支持、简单的文件上传、约定大于配置的契约式编程支持、基于注解的零配置支持等等。</p><p><code>SpringMVC</code> <strong>和</strong> <code>Struts2</code> <strong>的优略分析</strong> 共同点： 它们都是表现层框架，都是基于</p><p><code>MVC</code></p><p>模型编写的。 它们的底层都离不开原始</p><p><code>ServletAPI</code></p><p>。 它们处理请求的机制都是一个核心控制器。 区别：</p><p><code>Spring MVC</code></p><p>的入口是 <code>Servlet,</code> 而 <code>Struts2</code> 是</p><ul><li>Filter</li><li>Spring MVC</li></ul><p>是基于方法设计的，而 <code>Struts2</code> 是基于类，<code>Struts2</code> 每次执行都会创建一个动作类。所以 <code>Spring MVC</code> 会稍微比 <code>Struts2</code> 快些。 <code>Spring MVC</code> 使用更加简洁<code>,</code>同时还支持 <code>JSR303,</code> 处理 <code>ajax</code> 的请求更方便</p><p><code>(JSR303</code></p><p>是一套 <code>JavaBean</code> 参数校验的标准，它定义了很多常用的校验注解，我们可以直接将这些注解加在我们 <code>JavaBean</code> 的属性上面，就可以在需要校验的时候进行校验了。</p><ul><li>)</li><li>Struts2</li></ul><p>的 <code>OGNL</code> 表达式使页面的开发效率相比 <code>Spring MVC</code> 更高些，但执行效率并没有比 <code>JSTL</code> 提升，尤其是 <code>struts2</code> 的表单标签，远没有 <code>html</code> 执行效率高。</p></div>",1)])])}const V=o(r,[["render",t]]);export{l as __pageData,V as default};
